INSERT INTO quiz_questions (id, topic_id, level_number, statement, answer, hint, explanation, fun_fact, source, status, active, updated_at) VALUES
  ('my-cycle-1-01', 'my-cycle', 1, 'A period usually lasts between 2 and 7 days.', 'fact', 'Think of about a week.', 'Most periods last 2 to 7 days. If bleeding often lasts longer than 7 days, it is worth talking to a doctor.', 'Your very first period has a name: menarche.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-1-02', 'my-cycle', 1, 'Your cycle is counted from the first day of your period.', 'fact', 'Where does day 1 begin?', 'Day 1 is the first day of proper bleeding. The cycle runs until the day before your next period starts.', 'Logging day 1 each month is what lets Spot it predict your next period.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-1-03', 'my-cycle', 1, 'Every healthy cycle is exactly 28 days long.', 'myth', 'Is everyone the same?', 'Cycles of about 21 to 35 days are common, and yours can change a little from month to month.', '28 days is only an average, not a rule.', 'ACOG: Menstruation in girls and adolescents', 'draft', true, now()),
  ('my-cycle-1-04', 'my-cycle', 1, 'Periods are often irregular for the first year or two after they start.', 'fact', 'Your body is still learning a new rhythm.', 'Hormones take time to settle after periods begin, so early cycles often vary in length.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-1-05', 'my-cycle', 1, 'You lose about a cup of blood during a period.', 'myth', 'It looks like more than it is.', 'Most people lose around 2 to 3 tablespoons of blood over a whole period. Heavy periods can be more than this.', 'Period blood mixes with womb lining and mucus, which makes it look like more.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-1-06', 'my-cycle', 1, 'Any spotting between periods means something is wrong.', 'myth', 'Light spotting can have everyday causes.', 'Light spotting can happen around ovulation or with some medicines. If it keeps happening or worries you, see a doctor.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-1-07', 'my-cycle', 1, 'Period blood can contain small clots.', 'fact', 'Think about heavier days.', 'Small clots are common on heavier days. Clots bigger than about 2.5 cm are worth mentioning to a doctor.', NULL, 'NHS: Heavy periods', 'draft', true, now()),
  ('my-cycle-1-08', 'my-cycle', 1, 'Stress, big changes in weight or lots of exercise can make a period late.', 'fact', 'Your brain helps time your cycle.', 'Stress and big changes in weight or exercise can affect the hormones that control your cycle and delay a period.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-2-01', 'my-cycle', 2, 'Ovulation always happens on day 14.', 'myth', 'Does every cycle have the same length?', 'Ovulation moves with your cycle length. Day 14 is only an average for a 28-day cycle.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-2-02', 'my-cycle', 2, 'Ovulation is when one of the ovaries releases an egg.', 'fact', 'The name comes from the Latin for egg.', 'Each cycle, hormones signal an ovary to release an egg. This is called ovulation.', 'An egg is one of the largest cells in the human body.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-2-03', 'my-cycle', 2, 'An egg survives for about 12 to 24 hours after it is released.', 'fact', 'It is shorter than you might think.', 'After release, an egg lives for about a day. If it is not fertilised, it breaks down.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-2-04', 'my-cycle', 2, 'Ovulation usually happens about 12 to 16 days before your next period.', 'fact', 'Count back from the next period.', 'The time after ovulation is fairly steady, so ovulation usually falls 12 to 16 days before the next period.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-2-05', 'my-cycle', 2, 'Some people feel a twinge of pain on one side of their tummy when they ovulate.', 'fact', 'It has a German name: mittelschmerz.', 'Ovulation pain is common, harmless and usually lasts minutes to a day or two. See a doctor if it is severe.', NULL, 'NHS: Ovulation pain', 'draft', true, now()),
  ('my-cycle-2-06', 'my-cycle', 2, 'You ovulate during your period.', 'myth', 'Think about the middle of the cycle.', 'For most people, ovulation happens around the middle of the cycle, well after bleeding has stopped.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-2-07', 'my-cycle', 2, 'Around ovulation, vaginal mucus can become clear, slippery and stretchy, like raw egg white.', 'fact', 'Your body leaves clues.', 'Rising oestrogen before ovulation makes cervical mucus thinner and stretchier.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-2-08', 'my-cycle', 2, 'Your body temperature drops and stays low after ovulation.', 'myth', 'Progesterone is a warming hormone.', 'After ovulation, progesterone raises your resting temperature slightly, and it stays a little higher until your period.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-3-01', 'my-cycle', 3, 'The cycle has four phases: menstrual, follicular, ovulation and luteal.', 'fact', 'Bleed, build, release, wait.', 'The menstrual phase is your period, the follicular phase gets an egg ready, ovulation releases it and the luteal phase follows.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-3-02', 'my-cycle', 3, 'The luteal phase comes before ovulation.', 'myth', 'Luteal comes from the corpus luteum, which forms after release.', 'The luteal phase comes after ovulation and lasts until your next period.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-3-03', 'my-cycle', 3, 'The follicular phase starts on the first day of your period.', 'fact', 'It overlaps with bleeding.', 'The follicular phase begins on day 1 and lasts until ovulation, while a follicle and egg get ready.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-3-04', 'my-cycle', 3, 'Premenstrual symptoms usually show up in the week or two before a period.', 'fact', 'Think about the end of the cycle.', 'PMS symptoms like bloating, sore breasts and mood changes usually start in the luteal phase and ease once bleeding starts.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('my-cycle-3-05', 'my-cycle', 3, 'Oestrogen rises as an egg gets ready to be released.', 'fact', 'This hormone builds things up.', 'During the follicular phase, the growing follicle makes more and more oestrogen, which peaks just before ovulation.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-3-06', 'my-cycle', 3, 'Progesterone is mainly made after ovulation.', 'fact', 'It comes from what the follicle leaves behind.', 'After ovulation, the empty follicle becomes the corpus luteum, which makes progesterone.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-3-07', 'my-cycle', 3, 'If an egg is not fertilised, the womb lining is shed as a period.', 'fact', 'What happens to the lining?', 'When hormone levels fall at the end of the cycle, the womb lining comes away and leaves the body as a period.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-3-08', 'my-cycle', 3, 'The luteal phase changes a lot in length from cycle to cycle.', 'myth', 'Which phase tends to stay steady?', 'The luteal phase is usually steady at around 11 to 17 days. Differences in cycle length mostly come from the follicular phase.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('period-myths-1-01', 'period-myths', 1, 'You shouldn’t swim on your period.', 'myth', 'Think about what a tampon or a cup does.', 'Swimming is fine with a tampon or a cup, and gentle exercise can even ease cramps.', 'Water pressure can slow your flow a little while you are in the pool.', 'NHS: Periods', 'draft', true, now()),
  ('period-myths-1-02', 'period-myths', 1, 'Exercise makes period cramps worse.', 'myth', 'Moving can help muscles relax.', 'Gentle exercise like walking, swimming or stretching can ease period pain for many people.', NULL, 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-1-03', 'period-myths', 1, 'Periods sync up when people live together.', 'myth', 'What does the research say?', 'This idea is popular, but larger studies have not found good evidence that periods sync.', NULL, 'ACOG: Menstruation in girls and adolescents', 'draft', true, now()),
  ('period-myths-1-04', 'period-myths', 1, 'It is fine to shower or have a bath during your period.', 'fact', 'Warm water can even feel good.', 'Washing during your period is healthy and can help you feel fresh. A warm bath may ease cramps.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('period-myths-1-05', 'period-myths', 1, 'Period blood is dirty blood.', 'myth', 'What is it actually made of?', 'Period blood is blood and womb lining. It is a normal part of the cycle, not a sign of being unclean.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('period-myths-1-06', 'period-myths', 1, 'You shouldn’t wash your hair during your period.', 'myth', 'Is there any reason it would matter?', 'There is no health reason to avoid washing your hair, bathing or showering during your period.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('period-myths-1-07', 'period-myths', 1, 'Using a tampon can make you lose your virginity.', 'myth', 'What does virginity actually mean?', 'Virginity is about sexual activity, not tampons. Tampons can be used from your very first period.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-myths-1-08', 'period-myths', 1, 'Cold drinks make period pain worse.', 'myth', 'Is there evidence?', 'There is no good evidence that cold food or drinks cause period pain. Warm drinks may simply feel soothing.', NULL, 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-01', 'period-myths', 2, 'Period pain bad enough to miss school or work is just something to put up with.', 'myth', 'Pain that stops your day matters.', 'Very painful periods can have treatable causes such as endometriosis. It is worth seeing a doctor.', NULL, 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-02', 'period-myths', 2, 'A hot water bottle on your tummy can ease period cramps.', 'fact', 'Warmth relaxes muscles.', 'Heat on your tummy or back helps the muscles relax and is a simple way to ease cramps.', NULL, 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-03', 'period-myths', 2, 'Period pain happens when the muscles of the womb tighten.', 'fact', 'Your womb is a muscle.', 'Chemicals called prostaglandins make the womb muscle tighten to shed its lining, which can cause cramps.', NULL, 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-04', 'period-myths', 2, 'Painkillers such as ibuprofen can ease period pain, but they are not right for everyone.', 'fact', 'Check the label first.', 'Ibuprofen often helps period pain, but people with asthma or stomach problems should ask a pharmacist first.', NULL, 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-05', 'period-myths', 2, 'Everyone gets period pain.', 'myth', 'Is everyone the same?', 'Many people get some cramps, but not everyone does, and how strong it feels varies a lot.', NULL, 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-06', 'period-myths', 2, 'Period pain that gets worse every year is always normal.', 'myth', 'Changes are worth noticing.', 'Pain that gets worse over time can be a sign of a condition like endometriosis and should be checked.', NULL, 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-07', 'period-myths', 2, 'Gentle stretching or a short walk can help with cramps.', 'fact', 'Moving helps blood flow.', 'Light activity can ease cramps and lift your mood by releasing feel-good endorphins.', NULL, 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-08', 'period-myths', 2, 'Having period pain means you will have trouble getting pregnant one day.', 'myth', 'Pain and fertility are different things.', 'Most period pain is not linked to fertility problems. If pain is severe, a doctor can check for causes.', NULL, 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-3-01', 'period-myths', 3, 'It is fine to leave a tampon in for a whole day and night.', 'myth', 'How often should it change?', 'Tampons should be changed every 4 to 8 hours to lower the small risk of toxic shock syndrome.', NULL, 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-myths-3-02', 'period-myths', 3, 'Teenagers can use menstrual cups.', 'fact', 'Cups come in different sizes.', 'Menstrual cups come in smaller sizes and can be used by teenagers once they feel comfortable.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-myths-3-03', 'period-myths', 3, 'Pads should be changed regularly, about every 3 to 4 hours, even on light days.', 'fact', 'Freshness matters.', 'Changing pads regularly keeps you comfortable and helps prevent smells and irritation.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-myths-3-04', 'period-myths', 3, 'Toxic shock syndrome is only linked to tampons.', 'myth', 'Think about other products and causes.', 'Toxic shock syndrome is rare. It has been linked to tampons and cups but can also happen for other reasons.', NULL, 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-myths-3-05', 'period-myths', 3, 'Scented wipes or douches help keep the vagina clean.', 'myth', 'The vagina cleans itself.', 'The vagina is self-cleaning. Douches and scented products can upset its natural balance. Plain water outside is enough.', NULL, 'NHS: Vaginal discharge', 'draft', true, now()),
  ('period-myths-3-06', 'period-myths', 3, 'Period pants can be washed and used again.', 'fact', 'Think reusable.', 'Period pants are reusable. Rinse them in cold water, then wash as the label says.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-myths-3-07', 'period-myths', 3, 'You need to take out a menstrual cup to pee.', 'myth', 'Where is the cup sitting?', 'A cup sits in the vagina, and urine leaves through a separate opening, so you can pee as normal.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-myths-3-08', 'period-myths', 3, 'A tampon can get lost inside your body.', 'myth', 'Where does the vagina lead?', 'The opening of the cervix is far too small for a tampon to pass through, so it cannot get lost.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('body-changes-1-01', 'body-changes', 1, 'For girls, puberty usually starts somewhere between the ages of 8 and 13.', 'fact', 'There is a wide range.', 'Puberty can start any time from about 8 to 13, and starting earlier or later than friends is normal.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-02', 'body-changes', 1, 'Breast development is often one of the first signs of puberty.', 'fact', 'What changes first?', 'Breast buds, small lumps under the nipple, are often the first sign of puberty.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-03', 'body-changes', 1, 'Periods usually start before any other puberty changes.', 'myth', 'Periods tend to come later.', 'Periods usually start about two years after breasts begin to develop.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-04', 'body-changes', 1, 'Growth spurts are part of puberty.', 'fact', 'Think about getting taller.', 'During puberty you can grow several centimetres a year.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-05', 'body-changes', 1, 'Everyone goes through puberty at the same age.', 'myth', 'Look around a classroom.', 'Puberty starts and moves at different speeds for different people, and that is normal.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-06', 'body-changes', 1, 'Puberty is started by hormones sent from the brain.', 'fact', 'The control centre is in your head.', 'The brain releases hormones that tell the ovaries to start making oestrogen, which starts puberty.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-07', 'body-changes', 1, 'Sweating more during puberty is normal.', 'fact', 'Sweat glands change too.', 'Sweat glands become more active in puberty. Washing daily and using deodorant can help.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-08', 'body-changes', 1, 'Feeling moody during puberty means something is wrong.', 'myth', 'Hormones and growing up both play a part.', 'Changing hormones and new experiences can make moods go up and down. Talk to someone if you feel low a lot.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-01', 'body-changes', 2, 'It is common for one breast to be a little bigger than the other.', 'fact', 'Bodies are rarely perfectly even.', 'Breasts often grow at different speeds, and a small difference in size is very common.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-02', 'body-changes', 2, 'Stretch marks from growth spurts are harmful.', 'myth', 'They are a sign of fast growth.', 'Stretch marks are common when the body grows quickly. They are harmless and often fade over time.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-03', 'body-changes', 2, 'Hair growing under the arms and around the genitals is a normal part of puberty.', 'fact', 'Hormones cause new hair growth.', 'Body hair is a normal sign of puberty. Removing it or not is a personal choice.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-04', 'body-changes', 2, 'Gaining some weight during puberty is a normal part of growing.', 'fact', 'Your body is building.', 'Hips widen and the body stores a little more fat during puberty. This is healthy and expected.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-05', 'body-changes', 2, 'Breasts can feel sore or tender while they grow.', 'fact', 'Growing tissue can ache.', 'Tenderness is common while breasts develop and often comes and goes.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-06', 'body-changes', 2, 'Shaving makes hair grow back thicker.', 'myth', 'Does the root change?', 'Shaving cuts hair at the surface. Regrowth can feel stubbly but it is not thicker or darker.', NULL, 'Mayo Clinic: Hair removal myths', 'draft', true, now()),
  ('body-changes-2-07', 'body-changes', 2, 'Wearing a bra makes breasts grow faster.', 'myth', 'What controls breast growth?', 'Breast growth is driven by hormones. Bras are for comfort and support, not growth.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-08', 'body-changes', 2, 'Many girls are close to their adult height a year or two after their first period.', 'fact', 'Growth slows after periods start.', 'The biggest growth spurt usually comes before the first period, and growth slows down afterwards.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-3-01', 'body-changes', 3, 'Vaginal discharge is normal and helps keep the vagina clean.', 'fact', 'It has a job to do.', 'Discharge is fluid that keeps the vagina clean, moist and protected from infection.', NULL, 'NHS: Vaginal discharge', 'draft', true, now()),
  ('body-changes-3-02', 'body-changes', 3, 'Discharge often starts several months before the first period.', 'fact', 'It can be an early sign.', 'Many girls notice discharge in their underwear a few months to a year before their first period.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-3-03', 'body-changes', 3, 'Healthy discharge has no smell at all.', 'myth', 'A mild smell can be normal.', 'Healthy discharge can have a mild smell. A strong, fishy or unusual smell is worth checking.', NULL, 'NHS: Vaginal discharge', 'draft', true, now()),
  ('body-changes-3-04', 'body-changes', 3, 'Discharge changes through the cycle.', 'fact', 'Hormones change it.', 'Discharge can be thicker or thinner, cloudier or clearer at different points in your cycle.', NULL, 'NHS: Vaginal discharge', 'draft', true, now()),
  ('body-changes-3-05', 'body-changes', 3, 'Thick, white discharge with itching can be a sign of thrush.', 'fact', 'Think of cottage cheese.', 'Thrush is a common yeast infection. A pharmacist or doctor can recommend treatment.', NULL, 'NHS: Thrush', 'draft', true, now()),
  ('body-changes-3-06', 'body-changes', 3, 'You should wash inside your vagina with soap.', 'myth', 'It cleans itself.', 'Soap inside the vagina can cause irritation. Gently washing the outside with water or a mild unscented wash is enough.', NULL, 'NHS: Vaginal discharge', 'draft', true, now()),
  ('body-changes-3-07', 'body-changes', 3, 'Green, yellow or grey discharge with a strong smell is worth checking with a doctor.', 'fact', 'Colour can be a clue.', 'These changes can be signs of an infection, which is usually easy to treat.', NULL, 'NHS: Vaginal discharge', 'draft', true, now()),
  ('body-changes-3-08', 'body-changes', 3, 'Cotton underwear can help the area stay comfortable.', 'fact', 'Breathable fabrics help.', 'Cotton lets air through and can help prevent irritation and thrush.', NULL, 'NHS: Thrush', 'draft', true, now()),
  ('period-care-1-01', 'period-care', 1, 'Pads come in different absorbencies for lighter and heavier days.', 'fact', 'One size does not fit all days.', 'Using a lighter pad on light days and a heavier one on heavy days keeps you comfortable.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-1-02', 'period-care', 1, 'You should use the lowest absorbency tampon you need.', 'fact', 'More absorbent is not always better.', 'Using the lowest absorbency that works for your flow lowers the risk of toxic shock syndrome.', NULL, 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-care-1-03', 'period-care', 1, 'Many menstrual cups can be worn for up to 12 hours, but check the instructions.', 'fact', 'Cups hold more than tampons.', 'Cups collect blood rather than absorb it, so they can often stay in longer. Always follow the maker’s guidance.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-1-04', 'period-care', 1, 'Reusable cloth pads must be thrown away after one use.', 'myth', 'Think reusable.', 'Cloth pads are rinsed, washed and dried, then used again for months or years.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-1-05', 'period-care', 1, 'You can sleep with a tampon in if you put a fresh one in before bed and change it within 8 hours.', 'fact', 'Timing is key.', 'Tampons are safe overnight as long as they are not left in for more than 8 hours.', NULL, 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-care-1-06', 'period-care', 1, 'A menstrual cup should be cleaned well and sterilised between periods.', 'fact', 'Follow the care steps.', 'Most cups are boiled or sterilised between periods and rinsed during use. Check the instructions for your cup.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-1-07', 'period-care', 1, 'Only adults can use tampons.', 'myth', 'When can you start?', 'Anyone who has periods can use tampons, including from the first period, once they feel ready.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-1-08', 'period-care', 1, 'Period products should be kept somewhere clean and dry.', 'fact', 'Think about bathroom steam.', 'Storing products clean and dry helps keep them hygienic until you use them.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-2-01', 'period-care', 2, 'Tracking your period helps you be ready before it starts.', 'fact', 'That is what Spot it is for.', 'Knowing roughly when your period is due means you can pack products and plan ahead.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('period-care-2-02', 'period-care', 2, 'Getting enough sleep can help you cope with period and PMS symptoms.', 'fact', 'Rest affects how you feel.', 'Poor sleep can make tiredness and low mood feel worse. Regular sleep can help.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('period-care-2-03', 'period-care', 2, 'Sleep makes no difference to how you feel before a period.', 'myth', 'Think about tired days.', 'Sleep affects mood and energy. Getting enough can make PMS symptoms easier to manage.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('period-care-2-04', 'period-care', 2, 'Carrying a spare pad or tampon is a good idea when your period is due.', 'fact', 'Be prepared.', 'Periods don’t always arrive on time, so a spare in your bag saves stress.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('period-care-2-05', 'period-care', 2, 'Leaks mean you are using your products wrong.', 'myth', 'Leaks happen to everyone.', 'Leaks are common, especially on heavy days or overnight. Trying a different size or product can help.', NULL, 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-2-06', 'period-care', 2, 'Cold water helps get period stains out of clothes.', 'fact', 'Hot water can set the stain.', 'Rinse stains in cold water as soon as you can. Hot water can make blood stains harder to remove.', NULL, NULL, 'draft', true, now()),
  ('period-care-2-07', 'period-care', 2, 'You should avoid all exercise on heavy days.', 'myth', 'Listen to your body.', 'You can exercise on any day of your period. Gentle activity may even help you feel better.', NULL, 'NHS: Period pain', 'draft', true, now()),
  ('period-care-2-08', 'period-care', 2, 'Relaxing activities like breathing exercises or yoga can help with PMS.', 'fact', 'Calm the body, calm the mind.', 'Activities that lower stress can ease PMS symptoms for many people.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('period-care-3-01', 'period-care', 3, 'Needing to change a pad or tampon every 1 to 2 hours can be a sign of heavy periods.', 'fact', 'How fast is it filling?', 'Soaking through products this quickly, or bleeding through clothes, is a sign of heavy bleeding worth checking.', NULL, 'NHS: Heavy periods', 'draft', true, now()),
  ('period-care-3-02', 'period-care', 3, 'If your periods stop for 3 months or more, it is worth seeing a doctor.', 'fact', 'Missing several is different from one.', 'Periods that stop for 3 months or more can have many causes, and a doctor can help find out why.', NULL, 'NHS: Stopped or missed periods', 'draft', true, now()),
  ('period-care-3-03', 'period-care', 3, 'Feeling very tired, short of breath or dizzy with heavy periods can be a sign of low iron.', 'fact', 'Blood carries iron.', 'Losing a lot of blood can lower iron levels. A simple blood test can check for anaemia.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('period-care-3-04', 'period-care', 3, 'If you haven’t had a first period by 16, it is worth talking to a doctor.', 'fact', 'There is a usual age range.', 'Most people start by 16. If not, a doctor can check everything is developing as expected.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('period-care-3-05', 'period-care', 3, 'Severe period pain that painkillers don’t help should be checked by a doctor.', 'fact', 'Pain should be manageable.', 'Pain that stops normal life or does not ease with usual treatments can have a treatable cause.', NULL, 'NHS: Period pain', 'draft', true, now()),
  ('period-care-3-06', 'period-care', 3, 'Heavy periods are always normal if they run in the family.', 'myth', 'Families can share conditions too.', 'Heavy periods can run in families, but they can still have treatable causes and are worth checking.', NULL, 'NHS: Heavy periods', 'draft', true, now()),
  ('period-care-3-07', 'period-care', 3, 'A doctor can help with period problems, even if it feels embarrassing to talk about.', 'fact', 'Doctors hear this every day.', 'Period problems are very common, and doctors and nurses are used to talking about them.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('period-care-3-08', 'period-care', 3, 'A sudden high temperature, rash and feeling very unwell while using a tampon needs urgent medical help.', 'fact', 'These are warning signs.', 'These can be signs of toxic shock syndrome, which is rare but serious. Remove the tampon and get urgent help.', NULL, 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('hormones-101-1-01', 'hormones-101', 1, 'Hormones are chemical messengers carried in the blood.', 'fact', 'They carry signals around the body.', 'Hormones travel in the blood and tell different parts of the body what to do.', NULL, 'NHS: Endocrine system', 'draft', true, now()),
  ('hormones-101-1-02', 'hormones-101', 1, 'Your brain helps control your menstrual cycle.', 'fact', 'The cycle has a control centre.', 'Parts of the brain called the hypothalamus and pituitary gland send hormones that tell the ovaries what to do.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-1-03', 'hormones-101', 1, 'Oestrogen is only made in the ovaries.', 'myth', 'Other tissues help too.', 'The ovaries make most oestrogen, but fat tissue and the adrenal glands make some too.', NULL, 'NHS: Endocrine system', 'draft', true, now()),
  ('hormones-101-1-04', 'hormones-101', 1, 'A hormone called FSH helps eggs develop in the ovaries.', 'fact', 'Its name gives a clue: follicle-stimulating.', 'Follicle-stimulating hormone helps follicles, which hold eggs, to grow each cycle.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-1-05', 'hormones-101', 1, 'A surge of a hormone called LH triggers ovulation.', 'fact', 'This hormone is what ovulation tests look for.', 'Luteinising hormone rises sharply, and ovulation usually follows within about a day or two.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-1-06', 'hormones-101', 1, 'Hormone levels stay the same all month.', 'myth', 'Think about the phases.', 'Hormones rise and fall in a pattern through each cycle, which is why you may feel different at different times.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('hormones-101-1-07', 'hormones-101', 1, 'Female bodies make small amounts of testosterone too.', 'fact', 'It is not only a male hormone.', 'The ovaries and adrenal glands make small amounts of testosterone, which plays a part in energy and wellbeing.', NULL, 'NHS: Endocrine system', 'draft', true, now()),
  ('hormones-101-1-08', 'hormones-101', 1, 'Thyroid hormones can affect your periods.', 'fact', 'Your neck holds a clue.', 'An overactive or underactive thyroid can make periods heavier, lighter or irregular.', NULL, 'NHS: Underactive thyroid', 'draft', true, now()),
  ('hormones-101-2-01', 'hormones-101', 2, 'Oestrogen helps build up the lining of the womb.', 'fact', 'It builds things up.', 'In the first half of the cycle, oestrogen thickens the womb lining.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-2-02', 'hormones-101', 2, 'Progesterone helps keep the womb lining in place after ovulation.', 'fact', 'It holds things steady.', 'Progesterone keeps the lining ready in case an egg is fertilised.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-2-03', 'hormones-101', 2, 'When progesterone falls at the end of the cycle, a period starts.', 'fact', 'What happens when support drops?', 'If no pregnancy happens, progesterone drops and the lining is shed as a period.', NULL, 'NHS: Periods', 'draft', true, now()),
  ('hormones-101-2-04', 'hormones-101', 2, 'Oestrogen only affects the reproductive system.', 'myth', 'Think bones, skin and mood.', 'Oestrogen also affects bones, skin, the heart and mood.', NULL, 'NHS: Endocrine system', 'draft', true, now()),
  ('hormones-101-2-05', 'hormones-101', 2, 'Oestrogen helps keep bones strong.', 'fact', 'Bones need hormones too.', 'Oestrogen helps protect bone strength, which is one reason bones can weaken after menopause.', NULL, 'NHS: Osteoporosis', 'draft', true, now()),
  ('hormones-101-2-06', 'hormones-101', 2, 'Progesterone is highest during your period.', 'myth', 'When is it made?', 'Progesterone is highest in the luteal phase, after ovulation, and drops just before your period.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-2-07', 'hormones-101', 2, 'Oestrogen peaks just before ovulation.', 'fact', 'It helps trigger the LH surge.', 'Oestrogen climbs through the follicular phase and peaks just before ovulation.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-2-08', 'hormones-101', 2, 'Oestrogen causes breasts to develop during puberty.', 'fact', 'Which hormone starts puberty changes?', 'Rising oestrogen in puberty causes breast development and other body changes.', NULL, 'NHS: Stages of puberty', 'draft', true, now()),
  ('hormones-101-3-01', 'hormones-101', 3, 'Changing hormone levels can affect your mood across the cycle.', 'fact', 'Hormones reach the brain too.', 'Many people notice mood shifts at different points in the cycle, often before a period.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-02', 'hormones-101', 3, 'PMS is all in your head.', 'myth', 'Is it real?', 'PMS is a real set of physical and emotional symptoms linked to hormone changes.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-03', 'hormones-101', 3, 'Regular exercise can help ease PMS symptoms.', 'fact', 'Movement and mood are linked.', 'Being active can improve mood, sleep and tiredness linked to PMS.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-04', 'hormones-101', 3, 'PMDD is a severe form of premenstrual symptoms that can be treated.', 'fact', 'It is more than ordinary PMS.', 'Premenstrual dysphoric disorder causes severe mood symptoms before periods. Doctors can help with treatment.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-05', 'hormones-101', 3, 'Feeling low before your period means you have depression.', 'myth', 'Timing is the clue.', 'Low mood that comes before periods and lifts afterwards is usually linked to the cycle. If it lasts, talk to a doctor.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-06', 'hormones-101', 3, 'Keeping a symptom diary can help a doctor understand PMS.', 'fact', 'Patterns tell a story.', 'Logging symptoms for a couple of months shows whether they follow your cycle. Spot it can help.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-07', 'hormones-101', 3, 'Cutting down on caffeine can help some people with PMS.', 'fact', 'Think coffee, energy drinks and cola.', 'Caffeine can make anxiety, irritability and sleep problems worse for some people.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-08', 'hormones-101', 3, 'Hormones have no effect on sleep.', 'myth', 'Think about the nights before a period.', 'Hormone changes before a period can make it harder to sleep well for some people.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('skin-hormones-1-01', 'skin-hormones', 1, 'Spots often flare up in the days before a period.', 'fact', 'Watch your skin across a month.', 'Hormone changes before a period can make skin oilier and spots more likely.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-02', 'skin-hormones', 1, 'Acne is caused by dirty skin.', 'myth', 'What is happening under the skin?', 'Acne is linked to hormones, oil and blocked pores, not to being dirty.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-03', 'skin-hormones', 1, 'Hormones called androgens can make skin oilier.', 'fact', 'Even girls make them.', 'Androgens make oil glands larger and more active, which can lead to spots.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-04', 'skin-hormones', 1, 'Chocolate has been proven to cause acne.', 'myth', 'What does the evidence say?', 'There is no strong evidence that chocolate causes acne. A balanced diet is good for your skin.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-05', 'skin-hormones', 1, 'Squeezing spots helps them heal faster.', 'myth', 'It can push things deeper.', 'Squeezing can spread bacteria and cause scarring. It is better to leave spots alone.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-06', 'skin-hormones', 1, 'Acne is very common in teenagers.', 'fact', 'How many teens get spots?', 'Most teenagers get acne at some point, so you are far from alone.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-07', 'skin-hormones', 1, 'Spots can appear on the back and chest too.', 'fact', 'Not only the face.', 'Acne often shows up on the face, back and chest, where there are many oil glands.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-08', 'skin-hormones', 1, 'Only teenagers get hormonal acne.', 'myth', 'Think about adults too.', 'Hormonal acne can carry on into adulthood or start later in life.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-01', 'skin-hormones', 2, 'Washing your face twice a day with a gentle cleanser is enough for most people.', 'fact', 'More is not always better.', 'Washing more than twice a day can irritate skin and make acne worse.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-02', 'skin-hormones', 2, 'Scrubbing hard clears spots faster.', 'myth', 'Be gentle.', 'Harsh scrubbing irritates skin. Gentle cleansing is better for spots.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-03', 'skin-hormones', 2, 'Products labelled non-comedogenic are less likely to block pores.', 'fact', 'Comedones are blocked pores.', 'Choosing non-comedogenic make-up and moisturiser can help if you get spots.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-04', 'skin-hormones', 2, 'Darker skin does not need sun cream.', 'myth', 'Sun affects every skin tone.', 'All skin tones can be damaged by the sun, and sun can make dark marks from spots last longer.', NULL, 'NHS: Sunscreen and sun safety', 'draft', true, now()),
  ('skin-hormones-2-05', 'skin-hormones', 2, 'Some acne treatments can make skin dry or sensitive at first.', 'fact', 'Skin needs time to adjust.', 'Mild dryness or redness is common at the start. A pharmacist can advise on how to use treatments.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-06', 'skin-hormones', 2, 'Toothpaste is a good spot treatment.', 'myth', 'It is made for teeth.', 'Toothpaste can irritate and dry the skin. Products made for acne are a better choice.', NULL, 'British Association of Dermatologists: Acne', 'draft', true, now()),
  ('skin-hormones-2-07', 'skin-hormones', 2, 'Taking off make-up before bed helps your skin.', 'fact', 'Pores need to breathe overnight.', 'Make-up left on overnight can clog pores. Removing it gently helps.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-08', 'skin-hormones', 2, 'Acne treatments work overnight.', 'myth', 'Patience is key.', 'Most acne treatments take 6 to 8 weeks before you see a clear difference.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-01', 'skin-hormones', 3, 'Painful, deep spots that leave scars are worth seeing a doctor about.', 'fact', 'Some acne needs prescription help.', 'Severe acne can cause scarring, and prescription treatments can help prevent it.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-02', 'skin-hormones', 3, 'A pharmacist can help with mild acne.', 'fact', 'You don’t always need an appointment.', 'Pharmacists can recommend creams and gels for mild acne and tell you when to see a doctor.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-03', 'skin-hormones', 3, 'Acne that affects how you feel about yourself is a good reason to get help.', 'fact', 'Feelings count too.', 'Acne can affect confidence and mood. That alone is a good reason to ask for support.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-04', 'skin-hormones', 3, 'Dark marks left after spots are always permanent scars.', 'myth', 'Marks and scars are different.', 'Dark marks are often post-inflammatory pigmentation, which usually fades over months. Sun protection helps.', NULL, 'British Association of Dermatologists: Acne', 'draft', true, now()),
  ('skin-hormones-3-05', 'skin-hormones', 3, 'Extra hair on the face or body together with acne can be a sign of a hormone condition like PCOS.', 'fact', 'Look at the bigger picture.', 'When acne comes with extra hair growth or irregular periods, a doctor may check for PCOS.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('skin-hormones-3-06', 'skin-hormones', 3, 'You just have to wait for acne to go away by itself.', 'myth', 'Treatment exists.', 'Acne can be treated, so you don’t have to wait it out.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-07', 'skin-hormones', 3, 'Some prescription acne treatments need regular check-ups.', 'fact', 'Stronger medicines need monitoring.', 'Some stronger treatments need regular check-ups to make sure they are working safely.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-08', 'skin-hormones', 3, 'Sudden bad acne in adulthood is always caused by stress.', 'myth', 'There can be other causes.', 'Stress can play a part, but hormone conditions and medicines can also cause adult acne. A doctor can help.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('pcos-1-01', 'pcos', 1, 'PCOS stands for polycystic ovary syndrome.', 'fact', 'Poly means many.', 'PCOS is a common condition that affects how the ovaries work.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-02', 'pcos', 1, 'PCOS is rare.', 'myth', 'How common is it?', 'PCOS is common and is thought to affect about 1 in every 10 women.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-03', 'pcos', 1, 'People with PCOS have harmful cysts on their ovaries.', 'myth', 'What are the ‘cysts’ really?', 'The ‘cysts’ are small follicles that hold eggs. They are not harmful, and not everyone with PCOS has them.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-04', 'pcos', 1, 'PCOS can affect how often you ovulate.', 'fact', 'Think irregular cycles.', 'With PCOS, the ovaries may not release an egg every cycle, which can make periods irregular.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-05', 'pcos', 1, 'PCOS is caused by something you did.', 'myth', 'What does the research say?', 'The exact cause is not known, but it is linked to hormones and genes, not to anything you did.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-06', 'pcos', 1, 'PCOS can run in families.', 'fact', 'Genes play a part.', 'You are more likely to have PCOS if a close relative has it.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-07', 'pcos', 1, 'PCOS only affects the ovaries.', 'myth', 'Think about insulin, skin and mood.', 'PCOS can also affect insulin, skin, hair and mood.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-08', 'pcos', 1, 'There is no cure for PCOS, but its symptoms can be managed.', 'fact', 'Management is the goal.', 'Lifestyle changes and medicines can help with most PCOS symptoms.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-01', 'pcos', 2, 'Irregular or missing periods can be a sign of PCOS.', 'fact', 'Look at your cycle pattern.', 'Irregular periods are one of the most common signs of PCOS.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-02', 'pcos', 2, 'Extra hair on the face, chest or back can be a sign of PCOS.', 'fact', 'Higher androgens are a clue.', 'Higher androgen levels in PCOS can cause extra hair growth.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-03', 'pcos', 2, 'Everyone with PCOS has the same symptoms.', 'myth', 'PCOS looks different for different people.', 'Symptoms vary a lot. Some people have many, others only one or two.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-04', 'pcos', 2, 'Thinning hair on the head can be linked to PCOS.', 'fact', 'Androgens affect scalp hair too.', 'Some people with PCOS notice thinning hair or hair loss on the head.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-05', 'pcos', 2, 'One blood test alone can tell you if you have PCOS.', 'myth', 'Doctors look at several things.', 'PCOS is diagnosed from symptoms, blood tests and sometimes an ultrasound scan.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-06', 'pcos', 2, 'Oily skin and acne can be linked to PCOS.', 'fact', 'Hormones affect skin.', 'Higher androgens can make skin oilier and spots more likely.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-07', 'pcos', 2, 'Everyone with PCOS is overweight.', 'myth', 'PCOS affects all body types.', 'People of any weight can have PCOS, though it can make weight gain more likely.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-08', 'pcos', 2, 'Dark, velvety patches of skin can be linked to insulin resistance, which is common in PCOS.', 'fact', 'Look at the neck or armpits.', 'These patches, often on the neck or armpits, can be a sign the body is not using insulin well.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-01', 'pcos', 3, 'Regular physical activity can help manage PCOS symptoms.', 'fact', 'Movement helps insulin work.', 'Exercise helps the body use insulin better, which can ease PCOS symptoms.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-02', 'pcos', 3, 'There is one special diet that cures PCOS.', 'myth', 'Is there a magic menu?', 'No diet cures PCOS, but balanced eating can help manage symptoms.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-03', 'pcos', 3, 'For people who are overweight, losing a small amount of weight can improve PCOS symptoms.', 'fact', 'Small changes count.', 'Losing even about 5 percent of body weight can help with periods and other symptoms.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-04', 'pcos', 3, 'Medicines can help make periods more regular with PCOS.', 'fact', 'Doctors have options.', 'A doctor can suggest medicines to regulate periods and manage other symptoms.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-05', 'pcos', 3, 'PCOS means you can never have children.', 'myth', 'What does the evidence say?', 'Many people with PCOS have children, some with help from treatment.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-06', 'pcos', 3, 'PCOS can affect mood and self-esteem, and support is available.', 'fact', 'Feelings matter too.', 'People with PCOS are more likely to feel anxious or low. Talking to a doctor can help.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-07', 'pcos', 3, 'Once you are diagnosed with PCOS, you never need check-ups.', 'myth', 'Long-term health matters.', 'Regular check-ups help watch for things like blood sugar and blood pressure.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-08', 'pcos', 3, 'Good sleep and managing stress are part of looking after PCOS.', 'fact', 'Rest helps hormones.', 'Sleep and stress affect hormones and energy, so they matter for PCOS too.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('food-cycle-1-01', 'food-cycle', 1, 'Eating a balanced diet supports your body through your cycle.', 'fact', 'Variety matters.', 'A mix of fruit, vegetables, wholegrains and protein gives your body what it needs all month.', NULL, 'NHS: Eat well', 'draft', true, now()),
  ('food-cycle-1-02', 'food-cycle', 1, 'Skipping meals helps reduce bloating.', 'myth', 'Your body needs regular fuel.', 'Skipping meals can lower energy and mood. Small, regular meals are better.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('food-cycle-1-03', 'food-cycle', 1, 'Fruit and vegetables give you fibre that helps digestion.', 'fact', 'Think about your gut.', 'Fibre helps keep digestion regular, which can help with period-related tummy troubles.', NULL, 'NHS: Eat well', 'draft', true, now()),
  ('food-cycle-1-04', 'food-cycle', 1, 'Calcium is important for strong bones.', 'fact', 'Think milk, yoghurt and leafy greens.', 'Calcium helps build bones, especially important in your teens.', NULL, 'NHS: Calcium', 'draft', true, now()),
  ('food-cycle-1-05', 'food-cycle', 1, 'Wholegrains release energy more slowly than sugary snacks.', 'fact', 'Think steady energy.', 'Wholegrains help keep energy steady instead of quick highs and lows.', NULL, 'NHS: Eat well', 'draft', true, now()),
  ('food-cycle-1-06', 'food-cycle', 1, 'You need special ‘period foods’ to stay healthy.', 'myth', 'Everyday food is enough.', 'No special foods are needed. A normal balanced diet supports your cycle.', NULL, 'NHS: Eat well', 'draft', true, now()),
  ('food-cycle-1-07', 'food-cycle', 1, 'Drinking enough water matters on your period, just as at any other time.', 'fact', 'Stay topped up.', 'Staying hydrated helps energy and can ease headaches.', NULL, 'NHS: Water, drinks and your health', 'draft', true, now()),
  ('food-cycle-1-08', 'food-cycle', 1, 'Cutting out whole food groups is a healthy way to fix period symptoms.', 'myth', 'Balance is key.', 'Cutting out food groups can mean missing nutrients. Talk to a doctor or dietitian first.', NULL, 'NHS: Eat well', 'draft', true, now()),
  ('food-cycle-2-01', 'food-cycle', 2, 'Iron helps carry oxygen around your body.', 'fact', 'It is part of your red blood cells.', 'Iron is needed to make haemoglobin, which carries oxygen in red blood cells.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-02', 'food-cycle', 2, 'Heavy periods can lower your iron levels.', 'fact', 'Blood contains iron.', 'Losing a lot of blood each month can lead to low iron or anaemia.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-03', 'food-cycle', 2, 'Only red meat contains iron.', 'myth', 'Think plants too.', 'Beans, lentils, dark green leafy vegetables, nuts and fortified cereals all contain iron.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-04', 'food-cycle', 2, 'Vitamin C helps your body absorb iron from plant foods.', 'fact', 'Think oranges and peppers.', 'Eating vitamin C foods with iron-rich plants helps your body take in more iron.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-05', 'food-cycle', 2, 'Drinking tea with meals can reduce how much iron you absorb.', 'fact', 'Timing your cuppa matters.', 'Tea and coffee can make it harder to absorb iron, so have them between meals.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-06', 'food-cycle', 2, 'Feeling tired all the time is always normal on your period.', 'myth', 'Tiredness can have causes.', 'Some tiredness is common, but constant tiredness can be a sign of low iron and is worth checking.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-07', 'food-cycle', 2, 'It is fine to take iron tablets without checking with a doctor.', 'myth', 'Too much iron is a problem too.', 'Too much iron can be harmful. Check with a doctor or pharmacist before taking supplements.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-08', 'food-cycle', 2, 'Some breakfast cereals have added iron.', 'fact', 'Check the label.', 'Fortified cereals can be a useful source of iron. Look for iron on the nutrition label.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-3-01', 'food-cycle', 3, 'Food cravings before a period are common.', 'fact', 'Many people notice them.', 'Hormone changes before a period can increase appetite and cravings.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('food-cycle-3-02', 'food-cycle', 3, 'Cravings always mean your body is missing a nutrient.', 'myth', 'Is there proof?', 'There is little evidence that cravings mean a deficiency. They are more likely linked to hormones and mood.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('food-cycle-3-03', 'food-cycle', 3, 'Eating a lot of salty food can make bloating worse.', 'fact', 'Salt holds on to water.', 'Salt can make the body hold on to water, adding to bloating before a period.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('food-cycle-3-04', 'food-cycle', 3, 'Small, regular meals can help keep your energy and mood steady.', 'fact', 'Think little and often.', 'Eating smaller meals more often can help with PMS symptoms like tiredness and irritability.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('food-cycle-3-05', 'food-cycle', 3, 'Fizzy drinks help reduce bloating.', 'myth', 'Think about the bubbles.', 'Fizzy drinks can add gas and make bloating feel worse.', NULL, NULL, 'draft', true, now()),
  ('food-cycle-3-06', 'food-cycle', 3, 'Eating chocolate during your period is harmful.', 'myth', 'Enjoy in balance.', 'Chocolate is fine as part of a balanced diet. There is no need to feel guilty about cravings.', NULL, 'NHS: Eat well', 'draft', true, now()),
  ('food-cycle-3-07', 'food-cycle', 3, 'Too much caffeine can make some people feel more anxious or jittery before a period.', 'fact', 'Think coffee and energy drinks.', 'Cutting down on caffeine may help if you feel anxious or have trouble sleeping before your period.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('food-cycle-3-08', 'food-cycle', 3, 'Bloating before a period is caused by eating too much.', 'myth', 'Hormones are the main reason.', 'Hormone changes make the body hold on to water, which causes most pre-period bloating.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now())
